Test Description:
Checking the exit code of the command 'sh -c 'conf="$(named-checkconf -p 2>/dev/null)" && printf '"'"'%s\n'"'"' "$conf" | awk '"'"'/zone "\."/{z=1} z && /type[[:space:]]+hint;/{ok=1} z && /^};/{z=0} END{exit !ok}'"'"' && f="$(printf '"'"'%s\n'"'"' "$conf" |
     awk '"'"'/zone "\."/{z=1} z && $1=="file"{gsub(/[";]/,"",$2); print $2; exit} z && /^};/{z=0}'"'"')" &&
test -n "$f" && if [ "${f#/}" = "$f" ]; then
  d="$(printf '"'"'%s\n'"'"' "$conf" |
       awk '"'"'$1=="directory"{gsub(/[";]/,"",$2); print $2; exit}'"'"')";
  f="${d:-/etc/bind}/$f";
fi && test -r "$f" && awk '"'"'
  /^[[:space:]]*($|;)/ {next}
  {
    for (i=1; i<=NF; i++) {
      if ($i=="A" && i<NF) {seen=1; if ($(i+1)!="100.0.6.2") bad=1}
      if ($i=="AAAA") bad=1
    }
  }
  END {exit !(seen && !bad)}
'"'"' "$f"'' on 'pc3'
